-- =========================================================================================
-- BẢNG: laptops (Quản lý thiết bị/Sản phẩm)
-- =========================================================================================
CREATE TABLE laptops (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  serial VARCHAR(100),
  name TEXT,
  category VARCHAR(100),
  import_date DATE,
  warehouse_date DATE,
  location VARCHAR(100),
  charger_status VARCHAR(100),
  status VARCHAR(100),
  price_rmb NUMERIC DEFAULT 0,
  shipping_rmb NUMERIC DEFAULT 0,
  exchange_rate NUMERIC DEFAULT 3550,
  import_price_vnd NUMERIC DEFAULT 0,
  wholesale_price_vnd NUMERIC DEFAULT 0,
  retail_price_vnd NUMERIC DEFAULT 0,
  tracking_code TEXT,
  customer_note TEXT,
  battery_health INTEGER DEFAULT 100,
  warranty_supplier TEXT,
  is_locked BOOLEAN DEFAULT false,
  screen_status VARCHAR(100),
  camera_mic_status VARCHAR(100),
  mainboard_status VARCHAR(100),
  condition_note TEXT,
  seller VARCHAR(100),
  is_active BOOLEAN DEFAULT true,
  parts_history JSONB DEFAULT '[]'::jsonb,
  month_key VARCHAR(10),
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
  updated_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()),
  CONSTRAINT laptops_non_negative_values CHECK (
    COALESCE(price_rmb, 0) >= 0
    AND COALESCE(shipping_rmb, 0) >= 0
    AND COALESCE(exchange_rate, 0) >= 0
    AND COALESCE(import_price_vnd, 0) >= 0
    AND COALESCE(wholesale_price_vnd, 0) >= 0
    AND COALESCE(retail_price_vnd, 0) >= 0
  ),
  CONSTRAINT laptops_battery_health_range CHECK (
    battery_health IS NULL OR battery_health BETWEEN 0 AND 100
  )
);
ALTER TABLE laptops ENABLE ROW LEVEL SECURITY;
CREATE UNIQUE INDEX laptops_serial_unique_idx
  ON laptops (lower(btrim(serial)))
  WHERE serial IS NOT NULL AND btrim(serial) <> '';
