CREATE TABLE financial_records (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  record_type TEXT NOT NULL CHECK (record_type IN ('income', 'expense', 'refund', 'adjustment')),
  category TEXT NOT NULL,
  amount NUMERIC NOT NULL CHECK (amount > 0),
  order_id BIGINT REFERENCES orders(id) ON DELETE SET NULL,
  payment_id BIGINT REFERENCES payments(id) ON DELETE SET NULL,
  laptop_id BIGINT REFERENCES laptops(id) ON DELETE SET NULL,
  occurred_on DATE NOT NULL DEFAULT CURRENT_DATE,
  payment_method TEXT,
  note TEXT,
  recorded_by TEXT,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT timezone('utc'::text, now())
);
CREATE INDEX financial_records_date_idx ON financial_records (occurred_on DESC, id DESC);
CREATE INDEX financial_records_order_idx ON financial_records (order_id, occurred_on DESC);
ALTER TABLE financial_records ENABLE ROW LEVEL SECURITY;
