-- MIGRATION: 20261011_phase9_sales_operations_hardening.sql
-- Phase 9 live hardening: cross-workflow sale gates and immutable economic sources.

CREATE UNIQUE INDEX IF NOT EXISTS laptop_cost_components_trade_in_source_unique
 ON public.laptop_cost_components(source_id)
 WHERE source_type='TRADE_IN' AND cost_type='TRADE_IN_ACQUISITION' AND voided_at IS NULL;

CREATE OR REPLACE FUNCTION public.guard_active_reservation_order_assignment() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
 IF NEW.laptop_id IS NOT NULL
    AND current_setting('app.reservation_conversion',true) IS DISTINCT FROM 'on'
    AND EXISTS(
      SELECT 1 FROM reservations r
      WHERE r.laptop_id=NEW.laptop_id AND r.status='ACTIVE' AND r.expires_at>timezone('utc',now())
        AND r.order_id IS DISTINCT FROM NEW.id
    ) THEN
  RAISE EXCEPTION 'Laptop đang được giữ cho reservation khác';
 END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS orders_active_reservation_gate ON public.orders;
CREATE TRIGGER orders_active_reservation_gate
 BEFORE INSERT OR UPDATE OF laptop_id,requested_laptop_id ON public.orders
 FOR EACH ROW EXECUTE FUNCTION public.guard_active_reservation_order_assignment();

CREATE OR REPLACE FUNCTION public.convert_reservation_to_order(p_id uuid,p_order_id bigint,p_actor text,p_idempotency_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r reservations%ROWTYPE;o orders%ROWTYPE;l laptops%ROWTYPE;
BEGIN
 SELECT * INTO r FROM reservations WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy reservation';END IF;
 IF r.status='CONVERTED' THEN RETURN to_jsonb(r);END IF;
 SELECT * INTO l FROM laptops WHERE id=r.laptop_id FOR UPDATE;
 IF r.status<>'ACTIVE' OR r.expires_at<=timezone('utc',now()) OR NOT l.is_active OR lower(l.status)<>'available' THEN RAISE EXCEPTION 'Reservation không còn hiệu lực';END IF;
 SELECT * INTO o FROM orders WHERE id=coalesce(p_order_id,r.order_id) AND is_active FOR UPDATE;
 IF NOT FOUND OR o.order_status IN('cancelled','returned','prepared','shipping','done') THEN RAISE EXCEPTION 'Cần draft order hợp lệ để chuyển đổi';END IF;
 IF r.order_id IS NOT NULL AND r.order_id<>o.id THEN RAISE EXCEPTION 'Reservation đã thuộc order khác';END IF;
 IF o.laptop_id IS NOT NULL AND o.laptop_id<>r.laptop_id THEN RAISE EXCEPTION 'Order đã gắn laptop khác';END IF;
 PERFORM set_config('app.reservation_conversion','on',true);
 UPDATE orders SET laptop_id=r.laptop_id,requested_laptop_id=r.laptop_id,reservation_expires_at=r.expires_at,updated_at=timezone('utc',now()) WHERE id=o.id;
 UPDATE reservations SET status='CONVERTED',order_id=o.id,converted_at=timezone('utc',now()),updated_at=timezone('utc',now()) WHERE id=r.id RETURNING * INTO r;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('RESERVATION',r.id::text,'UPDATE',jsonb_build_object('event','RESERVATION_CONVERTED','order_id',o.id,'idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(r);
END $$;

CREATE OR REPLACE FUNCTION public.complete_trade_in_inspection(p_id uuid,p_mainboard_status text,p_findings text,p_checks jsonb,p_actor text,p_idempotency_key text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE i trade_in_inspections%ROWTYPE;entry jsonb;
BEGIN
 SELECT * INTO i FROM trade_in_inspections WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy inspection';END IF;
 IF i.status='COMPLETED' THEN RETURN to_jsonb(i);END IF;
 IF p_mainboard_status NOT IN('ORIGINAL','OFFICIAL_REPLACED','REPAIRED','UNKNOWN') OR jsonb_typeof(coalesce(p_checks,'[]'::jsonb))<>'array' OR jsonb_array_length(coalesce(p_checks,'[]'::jsonb))=0 THEN RAISE EXCEPTION 'Kết quả inspection không hợp lệ';END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(p_checks) LOOP
  IF entry->>'result' NOT IN('PASS','FAIL','WARNING','NOT_TESTED') OR btrim(coalesce(entry->>'check_key',''))='' THEN RAISE EXCEPTION 'Checklist không hợp lệ';END IF;
  INSERT INTO trade_in_check_items(inspection_id,check_key,result,notes) VALUES(i.id,upper(left(entry->>'check_key',60)),entry->>'result',left(coalesce(entry->>'notes',''),1000));
 END LOOP;
 UPDATE trade_in_inspections SET status='COMPLETED',mainboard_status=p_mainboard_status,findings=left(coalesce(p_findings,''),5000),completed_at=timezone('utc',now()) WHERE id=i.id RETURNING * INTO i;
 UPDATE trade_ins SET status='QUOTED',updated_at=timezone('utc',now()) WHERE id=i.trade_in_id;
 INSERT INTO activity_logs(entity_type,entity_id,action,changes,user_name) VALUES('TRADE_IN_INSPECTION',i.id::text,'UPDATE',jsonb_build_object('event','TRADE_IN_INSPECTION_COMPLETED','idempotency_key',p_idempotency_key),p_actor);
 RETURN to_jsonb(i);
END $$;

CREATE OR REPLACE FUNCTION public.guard_trade_in_economic_history() RETURNS trigger
LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' AND OLD.status IN('ACCEPTED','RECEIVED','CONVERTED_TO_INVENTORY') THEN RAISE EXCEPTION 'Trade-in đã cam kết kinh tế không thể xóa';END IF;
 IF TG_OP='UPDATE' AND OLD.status='INSPECTING' AND NEW.status='ACCEPTED' THEN RAISE EXCEPTION 'Trade-in phải hoàn tất inspection trước khi chấp nhận';END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('ACCEPTED','RECEIVED','CONVERTED_TO_INVENTORY')
    AND (NEW.agreed_value_vnd IS DISTINCT FROM OLD.agreed_value_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.inventory_laptop_id IS DISTINCT FROM OLD.inventory_laptop_id OR NEW.serial IS DISTINCT FROM OLD.serial) THEN
  IF NOT (OLD.status='RECEIVED' AND NEW.status='CONVERTED_TO_INVENTORY' AND OLD.inventory_laptop_id IS NULL AND NEW.inventory_laptop_id IS NOT NULL AND NEW.agreed_value_vnd=OLD.agreed_value_vnd AND NEW.order_id IS NOT DISTINCT FROM OLD.order_id AND NEW.serial IS NOT DISTINCT FROM OLD.serial) THEN RAISE EXCEPTION 'Nguồn kinh tế trade-in đã cam kết là bất biến';END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
DROP TRIGGER IF EXISTS trade_ins_economic_history ON public.trade_ins;
CREATE TRIGGER trade_ins_economic_history BEFORE UPDATE OR DELETE ON public.trade_ins FOR EACH ROW EXECUTE FUNCTION public.guard_trade_in_economic_history();

CREATE OR REPLACE FUNCTION public.guard_commission_history() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
BEGIN
 IF TG_OP='DELETE' AND OLD.status IN('APPROVED','PAID') THEN RAISE EXCEPTION 'Commission đã duyệt/chi không thể xóa';END IF;
 IF TG_OP='UPDATE' AND OLD.status IN('APPROVED','PAID') AND (NEW.amount_vnd IS DISTINCT FROM OLD.amount_vnd OR NEW.order_id IS DISTINCT FROM OLD.order_id OR NEW.beneficiary_type IS DISTINCT FROM OLD.beneficiary_type OR NEW.beneficiary_user_id IS DISTINCT FROM OLD.beneficiary_user_id OR NEW.beneficiary_name IS DISTINCT FROM OLD.beneficiary_name OR NEW.commission_type IS DISTINCT FROM OLD.commission_type OR NEW.calculation_basis IS DISTINCT FROM OLD.calculation_basis OR NEW.calculation_snapshot_json IS DISTINCT FROM OLD.calculation_snapshot_json) THEN RAISE EXCEPTION 'Commission đã duyệt là bất biến';END IF;
 IF TG_OP='UPDATE' AND OLD.status='PAID' AND NEW.status<>'PAID' THEN RAISE EXCEPTION 'Commission đã chi không thể đổi trạng thái';END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $$;
DROP TRIGGER IF EXISTS commissions_immutable ON public.commissions;
CREATE TRIGGER commissions_immutable BEFORE UPDATE OR DELETE ON public.commissions FOR EACH ROW EXECUTE FUNCTION public.guard_commission_history();

REVOKE ALL ON FUNCTION guard_active_reservation_order_assignment(),guard_trade_in_economic_history(),guard_commission_history() FROM PUBLIC,anon,authenticated;


-- MIGRATION: 20261012_phase9_commission_ledger_constraint_repair.sql
-- Remove legacy duplicate Phase 8 checks before enabling commission payouts.

DO $$
DECLARE constraint_name text;
BEGIN
 FOR constraint_name IN
  SELECT conname FROM pg_constraint
  WHERE conrelid='public.account_transactions'::regclass
    AND contype='c'
    AND pg_get_constraintdef(oid) ILIKE '%reference_type%'
 LOOP
  EXECUTE format('ALTER TABLE public.account_transactions DROP CONSTRAINT %I',constraint_name);
 END LOOP;
 FOR constraint_name IN
  SELECT conname FROM pg_constraint
  WHERE conrelid='public.account_transactions'::regclass
    AND contype='c'
    AND pg_get_constraintdef(oid) ILIKE '%transaction_type%'
 LOOP
  EXECUTE format('ALTER TABLE public.account_transactions DROP CONSTRAINT %I',constraint_name);
 END LOOP;
END $$;

ALTER TABLE public.account_transactions ADD CONSTRAINT account_transactions_reference_type_check
 CHECK(reference_type IN('PAYMENT','SUPPLIER_PAYMENT','SUPPLIER_REFUND','COD_SETTLEMENT','COMMISSION','MANUAL','TRANSFER'));
ALTER TABLE public.account_transactions ADD CONSTRAINT account_transactions_transaction_type_check
 CHECK(transaction_type IN('CUSTOMER_PAYMENT','COD_SETTLEMENT','SUPPLIER_PAYMENT','SUPPLIER_REFUND','COMMISSION_PAYMENT','MANUAL_IN','MANUAL_OUT','TRANSFER_IN','TRANSFER_OUT','OTHER'));


-- MIGRATION: 20261013_phase9_trade_in_obligation_repair.sql
-- Keep customer obligation consistent after a trade-in credit is accepted.
-- Money on orders uses million VND; trade_in_credit_vnd uses VND.

CREATE OR REPLACE FUNCTION public.enforce_order_customer_obligation()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_trade_in_credit_million numeric := greatest(coalesce(NEW.trade_in_credit_vnd, 0), 0) / 1000000;
BEGIN
  NEW.sale_price := greatest(coalesce(NEW.sale_price, 0), 0);
  NEW.amount_paid := greatest(coalesce(NEW.amount_paid, 0), 0);
  IF NEW.amount_paid + v_trade_in_credit_million > NEW.sale_price + 0.000001 THEN
    RAISE EXCEPTION 'Tiền đã thu và credit thu cũ vượt giá bán';
  END IF;

  NEW.debt_amount := greatest(NEW.sale_price - NEW.amount_paid - v_trade_in_credit_million, 0);
  NEW.payment_status := CASE
    WHEN NEW.payment_status = 'refunded' THEN 'refunded'
    WHEN NEW.debt_amount = 0 AND NEW.sale_price > 0 THEN 'paid'
    WHEN NEW.payment_status = 'cod' THEN 'cod'
    WHEN NEW.amount_paid > 0 THEN 'deposited'
    ELSE 'unpaid'
  END;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS orders_enforce_customer_obligation ON public.orders;
CREATE TRIGGER orders_enforce_customer_obligation
BEFORE INSERT OR UPDATE OF sale_price, amount_paid, debt_amount, payment_status, trade_in_credit_vnd
ON public.orders
FOR EACH ROW EXECUTE FUNCTION public.enforce_order_customer_obligation();

-- Repair only Phase 9 orders that already carry a trade-in credit.
UPDATE public.orders
SET debt_amount = debt_amount
WHERE trade_in_credit_vnd > 0;

-- The order row is authoritative for outstanding debt because it also includes
-- non-cash trade-in credit. Cash receipts remain a separate invoice figure.
CREATE OR REPLACE FUNCTION public.sync_invoice_payment_snapshot(p_order_id bigint)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE receipts jsonb; finance jsonb; ledger_total numeric; effective_paid numeric; payment_count bigint; current_order orders%ROWTYPE;
BEGIN
 SELECT * INTO current_order FROM orders WHERE id=p_order_id;
 IF NOT FOUND OR NOT EXISTS (SELECT 1 FROM invoices WHERE order_id=p_order_id) THEN RETURN; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.payment_date,p.id),'[]'),
        coalesce(sum(CASE WHEN p.payment_type='refund' THEN -p.amount ELSE p.amount END),0),
        count(*)
 INTO receipts,ledger_total,payment_count FROM payments p WHERE p.order_id=p_order_id;
 effective_paid := CASE WHEN payment_count > 0 THEN ledger_total ELSE coalesce(current_order.amount_paid,0) END;
 SELECT coalesce(jsonb_agg(to_jsonb(f) ORDER BY f.occurred_on,f.id),'[]')
 INTO finance FROM financial_records f WHERE f.order_id=p_order_id;
 UPDATE invoices SET snapshot = jsonb_set(
   jsonb_set(
     jsonb_set(
       jsonb_set(
         jsonb_set(
           jsonb_set(
             jsonb_set(snapshot,'{payments}',receipts,true),
             '{financial_records}',finance,true),
           '{paid}',to_jsonb(effective_paid),true),
         '{order,payment_status}',to_jsonb(current_order.payment_status),true),
       '{order,amount_paid}',to_jsonb(coalesce(current_order.amount_paid,ledger_total)),true),
     '{order,trade_in_credit_vnd}',to_jsonb(coalesce(current_order.trade_in_credit_vnd,0)),true),
   '{order,debt_amount}',to_jsonb(coalesce(current_order.debt_amount,0)),true)
 WHERE order_id=p_order_id;
END $$;

REVOKE ALL ON FUNCTION public.enforce_order_customer_obligation(), public.sync_invoice_payment_snapshot(bigint)
FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.sync_invoice_payment_snapshot(bigint) TO service_role;

DO $$
DECLARE v_order_id bigint;
BEGIN
  FOR v_order_id IN SELECT id FROM public.orders WHERE trade_in_credit_vnd > 0 LOOP
    PERFORM public.sync_invoice_payment_snapshot(v_order_id);
  END LOOP;
END $$;


-- MIGRATION: 20261014_phase9_reservation_integrity_repair.sql
-- Keep Phase 9 reservations authoritative across both physical and requested
-- order assignments, and prevent attaching an unrelated payment as a deposit.

CREATE OR REPLACE FUNCTION public.guard_active_reservation_order_assignment()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public, pg_temp
AS $$
BEGIN
  IF current_setting('app.reservation_conversion', true) IS DISTINCT FROM 'on'
     AND EXISTS (
       SELECT 1
       FROM public.reservations r
       WHERE r.status = 'ACTIVE'
         AND r.expires_at > timezone('utc', now())
         AND (r.laptop_id = NEW.laptop_id OR r.laptop_id = NEW.requested_laptop_id)
         AND r.order_id IS DISTINCT FROM NEW.id
     ) THEN
    RAISE EXCEPTION 'Laptop đang được giữ cho reservation khác';
  END IF;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION public.create_reservation(
  p_laptop_id bigint,
  p_customer_id bigint,
  p_order_id bigint,
  p_expires_at timestamptz,
  p_deposit_payment_id bigint,
  p_notes text,
  p_user_id uuid,
  p_actor text,
  p_idempotency_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  r public.reservations%ROWTYPE;
  l public.laptops%ROWTYPE;
  o public.orders%ROWTYPE;
  p public.payments%ROWTYPE;
BEGIN
  SELECT * INTO r FROM public.reservations WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN RETURN to_jsonb(r); END IF;

  PERFORM public.expire_reservations(p_actor);
  SELECT * INTO l FROM public.laptops WHERE id = p_laptop_id FOR UPDATE;
  IF NOT FOUND OR lower(l.status) <> 'available' OR NOT l.is_active OR l.is_locked THEN
    RAISE EXCEPTION 'Laptop không đủ điều kiện giữ máy';
  END IF;
  IF p_expires_at <= timezone('utc', now()) THEN
    RAISE EXCEPTION 'Thời hạn giữ máy không hợp lệ';
  END IF;

  IF p_order_id IS NOT NULL THEN
    SELECT * INTO o FROM public.orders WHERE id = p_order_id AND is_active FOR UPDATE;
    IF NOT FOUND OR o.order_status IN ('cancelled', 'returned', 'prepared', 'shipping', 'done') THEN
      RAISE EXCEPTION 'Chỉ có thể gắn reservation vào draft order đang hoạt động';
    END IF;
    IF (o.laptop_id IS NOT NULL AND o.laptop_id <> p_laptop_id)
       OR (o.requested_laptop_id IS NOT NULL AND o.requested_laptop_id <> p_laptop_id) THEN
      RAISE EXCEPTION 'Order đang tham chiếu laptop khác';
    END IF;
    IF p_customer_id IS NOT NULL AND o.customer_id IS NOT NULL AND p_customer_id <> o.customer_id THEN
      RAISE EXCEPTION 'Khách hàng của reservation không khớp order';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.orders existing_order
    WHERE existing_order.is_active
      AND existing_order.order_status NOT IN ('cancelled', 'returned')
      AND existing_order.id IS DISTINCT FROM p_order_id
      AND (existing_order.laptop_id = p_laptop_id OR existing_order.requested_laptop_id = p_laptop_id)
  ) THEN
    RAISE EXCEPTION 'Laptop đang được một order khác giữ hoặc bán';
  END IF;

  IF p_deposit_payment_id IS NOT NULL THEN
    IF p_order_id IS NULL THEN
      RAISE EXCEPTION 'Payment đặt cọc phải đi kèm order';
    END IF;
    SELECT * INTO p FROM public.payments WHERE id = p_deposit_payment_id;
    IF NOT FOUND OR p.order_id <> p_order_id OR p.payment_type = 'refund' OR p.amount <= 0 THEN
      RAISE EXCEPTION 'Payment đặt cọc không thuộc order hoặc không hợp lệ';
    END IF;
  END IF;

  INSERT INTO public.reservations(
    reservation_code, laptop_id, customer_id, order_id, status, reserved_by,
    expires_at, deposit_payment_id, notes, idempotency_key, created_by
  ) VALUES (
    public.next_salesops_code('RSV', 'public.reservations'::regclass, 'reservation_code'),
    l.id, p_customer_id, p_order_id, 'ACTIVE', p_user_id, p_expires_at,
    p_deposit_payment_id, left(coalesce(p_notes, ''), 2000), p_idempotency_key, p_actor
  ) RETURNING * INTO r;

  INSERT INTO public.activity_logs(entity_type, entity_id, action, changes, user_name)
  VALUES (
    'RESERVATION', r.id::text, 'CREATE',
    jsonb_build_object('event', 'RESERVATION_CREATED', 'laptop_id', l.id), p_actor
  );
  RETURN to_jsonb(r);
EXCEPTION
  WHEN unique_violation THEN
    SELECT * INTO r FROM public.reservations WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN RETURN to_jsonb(r); END IF;
    RAISE EXCEPTION 'Laptop đã có reservation đang hoạt động';
END;
$$;

REVOKE ALL ON FUNCTION public.guard_active_reservation_order_assignment(),
  public.create_reservation(bigint, bigint, bigint, timestamptz, bigint, text, uuid, text, text)
FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.create_reservation(bigint, bigint, bigint, timestamptz, bigint, text, uuid, text, text)
TO service_role;


-- MIGRATION: 20261015_cancelled_receivable_repair.sql
-- Cancelled, returned and fully refunded orders retain their original sale/debt
-- history, but they are no longer collectible customer receivables.

CREATE OR REPLACE VIEW public.customer_receivable_summaries AS
SELECT
  o.id AS order_id,
  o.customer_id,
  c.name AS customer_name,
  c.phone AS customer_phone,
  o.sale_price,
  o.amount_paid,
  o.debt_amount,
  o.payment_due_at,
  o.created_date,
  o.sale_online AS salesperson,
  (SELECT max(p.payment_date) FROM public.payments p WHERE p.order_id = o.id) AS last_payment_date,
  CASE
    WHEN o.payment_due_at IS NULL THEN 'NO_DUE_DATE'
    WHEN o.payment_due_at >= now() THEN 'NOT_DUE'
    WHEN now() - o.payment_due_at <= interval '7 days' THEN 'OVERDUE_1_7'
    WHEN now() - o.payment_due_at <= interval '30 days' THEN 'OVERDUE_8_30'
    WHEN now() - o.payment_due_at <= interval '60 days' THEN 'OVERDUE_31_60'
    ELSE 'OVERDUE_60_PLUS'
  END AS aging_bucket
FROM public.orders o
LEFT JOIN public.customers c ON c.id = o.customer_id
WHERE o.is_active
  AND o.debt_amount > 0
  AND o.order_status NOT IN ('cancelled', 'returned')
  AND o.payment_status <> 'refunded';

CREATE OR REPLACE FUNCTION public.get_financial_operations_summary()
RETURNS jsonb
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
WITH receivables AS (
  SELECT r.*
  FROM public.customer_receivable_summaries r
),
refund_due AS (
  SELECT r.id, sum(coalesce(i.agreed_refund_rmb, i.expected_refund_rmb, 0)) expected
  FROM public.supplier_returns r
  JOIN public.supplier_return_items i
    ON i.supplier_return_id = r.id
   AND i.status NOT IN ('CANCELLED', 'REFUNDED', 'REPLACED', 'REJECTED')
  WHERE r.status IN ('WAITING_REFUND', 'PARTIALLY_RESOLVED')
  GROUP BY r.id
),
refund_paid AS (
  SELECT supplier_return_id, sum(amount_rmb) paid
  FROM public.supplier_refunds
  GROUP BY supplier_return_id
)
SELECT jsonb_build_object(
  'generated_at', timezone('utc', now()),
  'customer_receivable_vnd', (SELECT coalesce(sum(debt_amount), 0) * 1000000 FROM receivables),
  'customer_receivable_orders', (SELECT count(*) FROM receivables),
  'receivable_aging', coalesce((
    SELECT jsonb_object_agg(aging_bucket, jsonb_build_object('orders', n, 'amount_vnd', amount_vnd))
    FROM (
      SELECT aging_bucket, count(*) n, sum(debt_amount) * 1000000 amount_vnd
      FROM receivables
      GROUP BY aging_bucket
    ) x
  ), '{}'::jsonb),
  'cod', jsonb_build_object(
    'outstanding_vnd', (SELECT coalesce(sum(outstanding_vnd), 0) FROM public.cod_receivable_summaries WHERE status IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED')),
    'in_transit_vnd', (SELECT coalesce(sum(expected_cod_amount_vnd), 0) FROM public.cod_receivable_summaries WHERE status = 'PENDING_DELIVERY'),
    'overdue_vnd', (SELECT coalesce(sum(outstanding_vnd), 0) FROM public.cod_receivable_summaries WHERE status IN ('WAITING_SETTLEMENT', 'PARTIALLY_SETTLED', 'DISPUTED') AND expected_settlement_at < now()),
    'disputed', (SELECT count(*) FROM public.cod_receivables WHERE status = 'DISPUTED')
  ),
  'supplier_payable_cny', (SELECT coalesce(sum(debt_rmb), 0) FROM public.purchase_batch_summaries WHERE status NOT IN ('DRAFT', 'CANCELLED', 'CLOSED')),
  'supplier_refund_pending_cny', (SELECT coalesce(sum(greatest(d.expected - coalesce(p.paid, 0), 0)), 0) FROM refund_due d LEFT JOIN refund_paid p ON p.supplier_return_id = d.id),
  'accounts', coalesce((SELECT jsonb_agg(to_jsonb(b) ORDER BY currency, code) FROM public.cash_account_balances b WHERE is_active), '[]'::jsonb),
  'reconciliation_differences', (SELECT count(*) FROM public.cash_account_balances WHERE is_active AND coalesce(last_difference, 0) <> 0)
);
$$;

REVOKE ALL ON public.customer_receivable_summaries FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.customer_receivable_summaries TO service_role;
REVOKE ALL ON FUNCTION public.get_financial_operations_summary() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.get_financial_operations_summary() TO service_role;


-- MIGRATION: 20261016_warranty_integrity_repair.sql
-- Keep warranty cases attached to the sold laptop and its originating order,
-- and prevent parallel open cases for the same physical device.

CREATE OR REPLACE FUNCTION public.enforce_warranty_case_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_order public.orders%ROWTYPE;
BEGIN
  NEW.status := lower(trim(coalesce(NEW.status, '')));
  IF NEW.status NOT IN ('received', 'checking', 'wait_parts', 'repairing', 'done', 'swap_device', 'refunded') THEN
    RAISE EXCEPTION 'Trạng thái bảo hành không hợp lệ';
  END IF;
  IF NEW.laptop_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu bảo hành phải gắn với laptop';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.laptop_id IS DISTINCT FROM OLD.laptop_id THEN
    RAISE EXCEPTION 'Không thể đổi máy gốc của phiếu bảo hành';
  END IF;

  IF NEW.order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.orders WHERE id = NEW.order_id;
    IF NOT FOUND OR NEW.laptop_id NOT IN (v_order.laptop_id, v_order.requested_laptop_id) THEN
      RAISE EXCEPTION 'Đơn gốc không thuộc máy đang tiếp nhận bảo hành';
    END IF;
  END IF;

  IF NEW.status IN ('done', 'swap_device', 'refunded') THEN
    NEW.resolved_date := coalesce(NEW.resolved_date, current_date);
  ELSE
    NEW.resolved_date := NULL;
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS warranty_cases_enforce_integrity ON public.warranty_cases;
CREATE TRIGGER warranty_cases_enforce_integrity
BEFORE INSERT OR UPDATE OF laptop_id, order_id, status, resolved_date
ON public.warranty_cases
FOR EACH ROW EXECUTE FUNCTION public.enforce_warranty_case_integrity();

CREATE UNIQUE INDEX IF NOT EXISTS warranty_cases_one_open_per_laptop_idx
ON public.warranty_cases(laptop_id)
WHERE status IN ('received', 'checking', 'wait_parts', 'repairing');

REVOKE ALL ON FUNCTION public.enforce_warranty_case_integrity()
FROM PUBLIC, anon, authenticated;


-- MIGRATION: 20261017_warranty_order_link_null_repair.sql
-- PostgreSQL NOT IN becomes unknown when one compared order laptop column is
-- NULL. Use null-safe comparisons so either valid laptop reference may match,
-- while an unrelated device is always rejected.

CREATE OR REPLACE FUNCTION public.enforce_warranty_case_integrity()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
DECLARE
  v_order public.orders%ROWTYPE;
BEGIN
  NEW.status := lower(trim(coalesce(NEW.status, '')));
  IF NEW.status NOT IN ('received', 'checking', 'wait_parts', 'repairing', 'done', 'swap_device', 'refunded') THEN
    RAISE EXCEPTION 'Trạng thái bảo hành không hợp lệ';
  END IF;
  IF NEW.laptop_id IS NULL THEN
    RAISE EXCEPTION 'Phiếu bảo hành phải gắn với laptop';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.laptop_id IS DISTINCT FROM OLD.laptop_id THEN
    RAISE EXCEPTION 'Không thể đổi máy gốc của phiếu bảo hành';
  END IF;

  IF NEW.order_id IS NOT NULL THEN
    SELECT * INTO v_order FROM public.orders WHERE id = NEW.order_id;
    IF NOT FOUND OR (
      NEW.laptop_id IS DISTINCT FROM v_order.laptop_id
      AND NEW.laptop_id IS DISTINCT FROM v_order.requested_laptop_id
    ) THEN
      RAISE EXCEPTION 'Đơn gốc không thuộc máy đang tiếp nhận bảo hành';
    END IF;
  END IF;

  IF NEW.status IN ('done', 'swap_device', 'refunded') THEN
    NEW.resolved_date := coalesce(NEW.resolved_date, current_date);
  ELSE
    NEW.resolved_date := NULL;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.enforce_warranty_case_integrity()
FROM PUBLIC, anon, authenticated;


INSERT INTO public.user_profiles(id,name,role,is_active,created_at,updated_at)
SELECT (data->>'id')::uuid,data->>'name',data->>'role',
       (data->>'is_active')::boolean,(data->>'created_at')::timestamptz,(data->>'updated_at')::timestamptz
FROM saved_profiles;
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;
NOTIFY pgrst, 'reload schema';
